input.command:
mkdir -p ~/.claude/hooks && cp ~/src/.claude/hooks/pre_tool_use.py ~/.claude/hooks/ && chmod +x ~/.claude/hooks/pre_tool_use.py
cat > ~/.claude/settings.json <<'EOF'
{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "/home/runner/.local/bin/uv run /home/runner/.claude/hooks/pre_tool_use.py"
          }
        ]
      }
    ]
  }
}
EOF
python3 -m json.tool ~/.claude/settings.json >/dev/null && echo ok; diff ~/src/.claude/hooks/pre_tool_use.py ~/.claude/hooks/pre_tool_use.py && echo same

